/*
 * prbs.h -- PRBS-11 (ITU-T O.153) generator and self-synchronising checker.
 *
 * PRBS-11 is the classic 64 kbit/s BER test pattern from the ISDN days: a
 * maximal-length sequence of period 2^11 - 1 = 2047 bits, generated by the
 * polynomial x^11 + x^9 + 1. On a 64 kbit/s B-channel (== G.711 @ 8 kHz, one
 * octet per sample) the pattern is simply serialised into the octet stream,
 * 8 bits per sample, and the far end verifies it bit-for-bit.
 *
 * We treat each RTP/G.711 payload octet as 8 raw B-channel bits and run the
 * pattern straight through them -- exactly like a hardware BERT on the B-channel.
 *
 * The checker self-synchronises: it loads 11 received bits to seed its LFSR,
 * verifies the seed against the following bits, then free-runs its own reference
 * and compares -- so a channel bit error is counted once and does NOT propagate
 * into the reference (non error-multiplying), which is what makes BER numbers
 * meaningful.
 */
#ifndef PRBS_H
#define PRBS_H

#include <stdint.h>

#define PRBS11_MASK 0x7FFu /* 11-bit LFSR state */

/* ---- generator ---- */
struct prbs_gen
{
    uint16_t reg;
};

void prbs_gen_init(struct prbs_gen *g, uint16_t seed);
/* Emit n octets, one PRBS bit per bit, MSB first. */
void prbs_gen_bytes(struct prbs_gen *g, uint8_t *out, int n);

/* ---- checker ---- */
enum prbs_state
{
    PRBS_HUNT = 0, /* loading 11 seed bits from the wire        */
    PRBS_VERIFY,   /* candidate seed on trial                   */
    PRBS_LOCK      /* synchronised, counting bit errors         */
};

struct prbs_chk
{
    uint16_t reg;
    int state;
    int fill;      /* seed bits loaded in HUNT                  */
    int verify_ok; /* consecutive good bits in VERIFY           */
    int locked;    /* currently in LOCK                         */

    /* interpretation of the octet stream (auto-probed by the caller) */
    int lsb_first; /* bit order within each octet               */
    int invert;    /* stream is bit-inverted                    */

    /* Loss-of-sync monitor: a sliding window of measured bits. A phase slip
     * yields a ~50% error rate (not 100%), so consecutive-error counting can't
     * see it -- we must watch the error RATE over a window. A window is only
     * committed to the totals once it passes; a window whose error rate exceeds
     * the loss threshold declares loss of sync and is discarded (it is a slip,
     * not real channel errors), then the checker re-hunts. */
    unsigned win_bits;
    unsigned win_errs;

    /* committed stats (in-sync bits/errors only) */
    unsigned long long bits;
    unsigned long long errors;
    unsigned resyncs; /* loss-of-sync events                     */
};

void prbs_chk_init(struct prbs_chk *c, int lsb_first, int invert);
/* Force the checker back to HUNT, e.g. after a detected RTP frame loss so the
 * pattern slip is re-acquired instead of billed as a huge error burst. */
void prbs_chk_resync(struct prbs_chk *c);
void prbs_chk_bit(struct prbs_chk *c, int rx_bit);
void prbs_chk_bytes(struct prbs_chk *c, const uint8_t *in, int n);
double prbs_chk_ber(const struct prbs_chk *c);

#endif
